import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易傳燈卷二","description":"易傳燈 - 易傳燈卷二","frontmatter":{"title":"易傳燈卷二","description":"易傳燈 - 易傳燈卷二"},"headers":[],"relativePath":"classics/yichuandeng/003.md","filePath":"classics/yichuandeng/003.md"}'),n={name:"classics/yichuandeng/003.md"};function c(r,p,i,_,o,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="易傳燈卷二" tabindex="-1">易傳燈卷二 <a class="header-anchor" href="#易傳燈卷二" aria-label="Permalink to “易傳燈卷二”">​</a></h1><p>欽定四庫全書</p><p>宋徐氏撰坎上八卦 比需屯井既濟蹇節</p><p>坎， 坎上坤下，眾陰推戴，一陽處九五之位，日「比」。坎九五剛中在上，眾陰下戴，無一人敢後者，故為「比」。比本乎坤，為易之門，行乎震、離、兌、乾之上為屯。既濟、節、需四卦皆坎在上而陽進之卦，故屯者，坎上震下，其上之坎六四，上六輔九五，膏澤不流，為陰所害，下有震初九，居正得民，宜建為侯。若既濟者，坎上離下，下離攻坎，三年克之為憊也。坎上兌下，兌二陽攻坎苦節，故曰「節」。坎上乾下，乾三陽需待以攻坎，六四「需血出穴」，故曰「需」。坎二小人得君於上，為下陽所攻，至需極矣。自需轉而行巽、坎、艮，為井、坎、蹇之三卦，坎處陽之卦也。故井者，坎上巽下，言以井蓄水不汲用為廢井，故繇辭「無喪無得，往來井井，汔至未繘井，未有功」。巽下二陽皆無與行惻，殆如東漢黨錮之禍，不見用於君，此坎處君子，像舊井之不用也。若坎上坎下曰「習坎」，重險也。上坎上六失道，下坎初六失道，坎之為患，九二、九五皆被患者。九二坎有險，九五坎不盈，其為小人患明矣。若蹇者，坎上艮下，上坎九五爻為大蹇之文，坎為君患，雖得朋來，而未能免咎也。下體之艮，皆見險能止以為知，故九三往蹇來反，為內所喜，故曰「蹇」也。坎體二小人夾輔陽君於上，亂政害國，讒毀君子。易以井、坎、蹇卦序之，學者可不考哉！坎下八卦 訟渙困坎未濟習 蒙解師 坎，陷也。一陽陷於二陰之中，二陰則為陷者也。其卦凡八，凡坎處於下體者，九二皆自上來陷，故聖人有「剛來得中」之文。訟九二之彖曰「剛來而得中」，故九二爻有「歸逋」之象。困九二之彖曰「剛掩」，言九二見掩於陰而致困。九二能以酒食自養，故「朱紱方來」，言人君以臣服起用者也。茲九二所以為「貞大人吉」也。初六、六三為困於九二，故六三非所困而困，又處於剛上，所以致不祥之兇。解九二自震九四而來，因小人致解。九二直己自明，故曰「獲三狐」，得中直之道。六三處非其分，負且乘，故致寇至。未濟九二自五而來，能曳其輪而不行，所以貞吉。初六不知極而吝，六三未濟徵而兇，皆害二者也。訟、困、未濟、解四卦，坎處於乾、兌、離、震之下，其九二皆自上來陷者也。若坎處於巽、坎、艮、坤之下者，為渙、坎、蒙、師，與前一義也。然坤上坎下為師，五陰用一陽帥師，則師九二非由上來陷者也。渙九二彖言「剛來不窮」，蓋六四本六二也，六二上奪九四之位，故九四下為九二，有「渙奔其機」之文，言處於二，得所安也。初六之順於九二、六三，則志在外，故曰「渙其躬」。若「習坎」之卦，上陷人君，而又下陷君子，故曰「重險」。九二在陷中，故曰「坎有險，求小得」。初六、六三為陷者也。初六失道既兇，六三來之坎坎，為下石之計，終無功也。小人之陷君子，雖能陷其身，而自小人視之，何功之有？清議所不容，必不自免其兇也。師九二在下得中，帥師之主。六三處九二之上，又欲為掌兵之權，權不出於一，所以致兇。蒙九二「以童蒙求我」，而為「包蒙納婦，子之克家」者也。而六三行不順，不有其躬，而依於九二，聖人所戒也。離上八卦 大有、噬、鼎、晉、嗑、未濟、睽、旅、</p><p>離 離，中女，陰卦也。先天八卦，二陽夾輔一陰於中，權籍二陽也。離乘乾為「大有」，六五得位，上下應之，曰「大有」。自大有本乎乾，為易之門。行乎巽、坎、艮、坤之上，為鼎、未濟、旅、晉四卦，皆離在上而陰進之卦，故離上巽下諸爻未有用也。離上坎下為未濟，九二，男之窮，故曰「未濟」。離上艮下為旅，離之九三，焚次喪僕，故曰「旅」。離上坤下為晉，晉下三陰，未遂其晉也。若離行乎震、離、兌之上，為噬嗑、離、睽三卦，離處陰之卦也。噬嗑之卦，離上震下，有位者皆用噬，而初、上則受罪者。離明在上，威動於下，用刑獄以儆於有位，非如乾命震而陰不為妄，此噬而後合，幸柔得中而上行也。離上離下為離上離，九四、上九輔六五以離，「王公致吉」。其下離，六二「黃離元吉」，故「畜牝牛吉」也。若睽者，離上兌下，離體二陽夾輔，陰君於上，多疑寡合，憎疾小人，故六三「輿曳」、「牛掣」為「睽」也。上下睽異，故九四、上九孤立於朝，為「小事吉」也。離下八卦 同人、家人、革、濟、離、賁、豐、明夷。既</p><p>離處下體，六二皆自上來，麗乎兩陽之間，兩陽所以處此陰也，當隨卦而言其義。同人之離，乃乾處陰於下之中而與之同，乾為九四、九三之間，乾興大師克之，得與二遇也。革之下離，乃兌之處陰也，革六二任離體二陽之中，革服於陽，巳日乃革之，故「徵吉」也。若離之離，乃止離之處陰也，六二依於二陽，柔麗中正，得所麗也，故曰「黃離元吉，畜牝牛吉」也。豐下之離，乃震處陰也。六二在離之中，為二陽所處。當豐之時，幽暗不明，不可以往，往得疑疾，「有孚發若，吉」。家人之離，巽處陰也。離體在下，初九、九三嚴於己以正家，六二柔順，不能有立，無所遂，但在「中饋」則吉。既濟之離，陰失位於上，今處於下，故六二「婦喪其茀，喪其為飾，無以為容，勿逐，七日得」，以中順之道，得所麗也。賁下之離，君子小人往來為文，故六二在兩陽間，得所麗為賁。明夷下離當陽剛誅陰之時，九三「南狩」，得其大首，而六二自上而下，順於二陽，故用拯馬壯吉，順以則也。茲離在下八卦各有旨也。艮上八卦， 剝、畜、頤、蠱、賁、蒙、損、艮大</p><p>艮重坤上一陽乘五陰為剝者，陰剝陽也。陽非可剝也，五陰恃眾而剝之，故艮乘坤曰剝。剝本乎坤，為易之門，故艮行。震、離、兌、乾之陽者，為頤。賁、損、大畜四卦，皆陽生於下之卦。若頤者，艮上震下，艮一陽上窮，震一陽下生，四陰中盛而陽微，故頤者，陰養陽之卦。故聖人有「觀頤自求口實」之文。初九不能自求，為小人所誚，致有「觀我朵頤」之兇。賁者，艮上離下，柔來文剛，剛上文柔，君子小人之相為賁也。損者，艮上兌下，損下益上，損三益上，損剛益柔，為損。大畜，艮上乾下，乾三陽為艮所畜，曰「大畜」。若艮處於巽、坎、艮之上者，為蠱、蒙、艮三卦為陽為陰，用也。艮上巽下，為蠱，剛上柔下，與之幹蠱。艮上坎下為蒙，九二為「發矇」也。艮上艮下為艮，下不求於上，故「不獲其身」；上不求於下，故「不見其人」。茲為上下敵應，不相與也，所以為艮也。艮下八卦 遁、漸、鹹、蹇、旅、艮、小過、謙。</p><p>艮者，止也。陽止於二陰之上，非陰止也。二陰長於下，一陽止於上，學者當究二陰何以為進身之計，一陽何以為處陰之計。而或者以為陽止陰，非也。故艮重於下者凡八卦，其六二皆有進志，九三皆有溺二之意。然究象辭，聖人每非三之與二也。遁六二用中順之道，固執於陽，莫之能解，六二依陽以進也，九三繫戀於二，故聖人以為畜臣妾則吉，而謂其不可大事也。鹹六二之「鹹其腓」，望陽之來感，而貴於居吉，則不失矣。然九三隨人以為感，聖人以為吝道也。旅六二之「即次」，進得所安，而九三在旅為與下之道，聖人所以傷其「喪童僕」也。小過六二「遇其臣不及其君」，得所遇於九三矣。而九三以陰過盛而乃防之，故致「從或戕」之兇。四卦艮重於乾、兌離震之下者也。若艮處於巽、坎艮坤之下者，曰漸、蹇、艮、謙。漸之六二「鴻漸於磐」，言進得所安也。九三之「徵」而不復，致二之「婦孕」而不育，而聖人謂三之「離群醜」也。蹇六二盡匪躬之節，而九三來反為內所喜，而聖人有「貞吉」與「無尤」之辭。艮六二不拯其隨，未退聽於九三，而九三之「艮其限」，自以止為道，不復顧於二也。謙六二之「鳴謙」，心中自得，而九三亦以謙自處，然其相得之情，觀於「鳴謙」，義可知矣。兌上八卦 夬萃大過革困兌鹹隨 兌重乾上，一陰乘五陽為夬。夬，決柔也。一陰一陽之謂道，陰非可決也，五陽恃眾而決之，故兌乘乾曰「夬」。夬本乎乾，為易之門，故兌行乎巽、坎、艮、坤之陰者為大過。困、鹹、萃四卦皆陰生於下之卦。若大過者，兌上巽下，兌之一陰上窮，巽之一陰下生，為本末弱，陽盛於中而本末弱，為棟橈之象，故曰「大過」。若困者，兌上坎下，坎之九二乃上剛掩於二為困。困之九二自上而來，揜於二也。剛揜有言不信，初六、六三乃為困於九二者，九二以酒食自養，故能有慶。若鹹者，兌上艮下為鹹，柔上剛下，感應相與曰「鹹」。萃者，兌上坤下坤，三陰下盛，言人民萃聚也。大過、鹹、萃皆陰生長之卦。兌行於震、離，兌為隨、革、兌三卦，皆處陰上之卦。兌上震下為隨，初九乃剛來下柔，得眾陰之隨，故曰「隨」。兌上離下為革，離之二陽處陰，而陰革服也。兌上兌下為兌，言陰說從也。兌重於震、離，兌之上為隨、革、兌三卦，言陰之隨而革且說也。自夬生大過、困、鹹、萃皆陰生於下之卦，以至為隨、革、兌，而陰隨革且說。易序兌於後，言順天應人，厥有旨矣。兌下八卦 履、孚兌、節、睽、損、歸妹中臨</p><p>兌者，說也。一陰處於二陽之上，處非其所，故求說乎陽，冀得所安也。故兌體重於八卦之下。六三多求說於陽，二陽在下，難乎其處此也。履六三履剛而處上，六三能說而應乾，故免咥人之兇，而論其才，則不足取也。兌六三則曰「來，兌」，來說於陽，所以兇。「臨」之六三以二陽之長則甘臨，亦求說於陽，故「無攸利」。歸妹六三反歸為娣，禮以從人，未當也。損六三當得友之時，無所損也。「節」六三當君子疑畏之際，不節而嗟，無所歸咎，嗟為君子所誅也。睽時，上下不相和同之際，六三疑畏，欲行而輿曳，欲順而牛掣，雖無初而有終，終則遇剛也。身處危疑，據剛之上，處非所安，故疑懼如此。若「中孚」則不然，疑其攻己，或鼓或罷，或泣或歌，始欲攻之，終安其所，蓋其處位不當故也。</p><p>文王之重卦，必嚴於上下二體之辨。上為何卦，下為何卦，而後立之卦。觀其卦象，系之繇辭，以明吉凶。其剛柔相推之變，先後反對之序，無不該於本卦二體之內，然後發揮於剛柔，而明其爻。非於本卦六爻之外，而即復、姤、臨、遁、泰、否六卦為之母，以論外變也；非以互體動爻之外，取象而為辭也。如需後有訟，「需」，乾三陽在下，攻坎出穴之卦。訟，乾三陽在上，一陽歸逋之卦。蓋八卦成列，乾右有巽、坎、艮三卦，其「坎」者，乾之上陽來陷於二也。故訟卦有「剛來得中」之文，爻有「不克訟，歸逋」之文。朱漢上不究八卦成列之圖象在其中之語，乃因訟曰「剛來得中」，無妄曰「剛自外來而為主於內」。朱以訟者遁三之二，無妄者遁三之初九。言外者皆自外。朱謂初、二兩爻視三則外矣。朱蓋以復、姤、臨、遁、泰、否六卦言變，而不知非易之變象也。愚未見內體三爻自分內外也。若無妄卦乾上震下，其初九有「剛自外來為主於內」之文。蓋乾之重卦凡八卦，乾、姤、訟、遁、否、無妄、同人、履。皆乾在上所重之卦，其下體所乘訟、遁、無妄者，皆乘三男，其陽皆自上來而處於內者也。朱漢上不以乾重卦為無妄之所本，蓋無妄自否來也。否，坤之三陰內乘乾，即命震以一陽為主於內，故震之一陽自乾外來，為內之主。由是陰畏震威，不為妄而邪惡屏息矣。茲天之命震為主，自乾而來，而非遁自三之初，為無妄之初九也。籲！重卦之上下二體，即有上下剛柔相推之象，本於八卦之成列，而後有八卦之相錯。數往者以順而數其往，知來者以逆而知其來，非可指復、姤、臨、遁、泰、否六卦為之母，而妄為卦變之往來。後之學者，不能於每卦上下論相乘相感之理，而推聖人觀象之旨，不得其要領，而於卦外言說，或言爻應，或言世變，或言互體，或言變體，自以為立論出於三聖所見之表。蓋自漢以下，萬人一律。籲，易道為異說所汨，可勝嘆哉！宜王通氏謂「九師興而易道微也」，宜王弼之有陰謫也。</p><p>易言「元亨利貞」凡七處，乾坤「元亨利貞」二處，彖謂之四德，聖人無所增損其義也。自「屯」而下，彖皆作「大亨」，以正釋之，而於「利」之一字，不連本文也。然後知「元亨貞」者，卦中自有「元亨貞」之德，而文王於「貞」上斷之以「利」於「貞」而已。此夫子所以不連「利」於「貞」為卦中之義也。屯曰「大亨貞」，隨曰「大亨貞」，無妄曰「大亨以正」，臨曰「大亨以正」，革曰「大亨以正」，皆不連「利」字者，乃知「利」者，文王之斷辭所加也。今而後讀「元亨」為一句，「利貞」為一句，庶得孔氏之意。</p><p>易有「安貞」、「艱貞」、「居貞」之辨，又有「女子貞」、「幽人貞」、「婦人貞」、「武人貞」、「牝馬貞」之別。其「安」「居」與「艱」，皆以字義為「貞」也。其女子、幽人、婦人、武人等貞，皆以人物為象也。「貞」於「安」，如坤卦「安貞」，訟九四「安貞吉」。貞於「居」，如屯爻「利居貞」。貞於艱，如泰九五「艱貞無咎」，明夷「利艱貞」，如大畜九三。「利艱貞」，如噬嗑九四「利艱貞吉」。此皆以字義為「貞」也。其「女子貞」者，屯六二爻言「女子貞」。又「幽人貞」者，履九二爻；「利幽人貞」者，歸妹九二之爻；「貞婦人吉」者，恆六五之爻。「貞大人吉」者，困之彖謂九二也。「貞丈人吉」者，師彖謂九二也。蓋以字義為「貞」者，當詳安居艱難之義。以人物為「貞」者，當詳婦人、女子、幽人、丈人、武人之義。外有「利君子貞」、「大貞」、「小貞」，皆可詳也。「貞」者，事事之幹，能詳究聖人立貞文多等之理，則知「利貞」、「貞吉」、「貞厲」、「貞吝」者，其義輕重，皆可沿而知之矣。</p><p>易爻以「血」為象，皆以有所傷為義，非以坎卦為血也。坤上六「其血玄黃」，言上六與陽戰，兩有所傷也。此豈坎卦哉？需六四「需於血」，言六四為三陽所攻，有所傷而去也。小畜六四言「血去」，以六四結知於君，免為三陽所害。渙上九言「血去」，以九陽明能遠害全身，免為六四所害也。小畜與渙皆巽體，豈皆坎卦哉？諸解者以坎為血卦，見諸爻以血為象者，牽強附會，以坎為說。籲，亦誣矣。</p><p>易以十年、三年、三歲為爻象者，以爻之吉凶輕重為久近之數。然十年為數之至重也。如屯六二「女子貞，十年乃字」。言六二有乘剛之難，義不從寇，故久而後反常乃字也。覆上六「迷復行師，自取其兇，十年不克徵」。所以為兇之至重也。又如頤六三拂亂其頤養之道，貞久於拂，大悖於道，雖十年勿用，故皆以十年為象也。外以三年、三歲為象者，比之十年為兇之輕，而數至於三，亦罹罪之重也。如同人伏戎敵剛，知其義不可與大師為敵，故至三年不敢興戎也。坎上六失事君之道，徽纆叢棘，兇至三歲不得免也。困初六坐受其困，致不明之災，在下而為困於人，自罹其困，雖三歲不覿也。豐上六豐大其屋，蔀蔽於家，失道無助，雖三歲亦不覿也。茲易以三年言得兇之重也。外既濟以「三年克鬼方」為憊，未濟以「三年伐鬼方」為志行，隨爻取象，各不同也。然易象以三數為重，「王三錫命」，示賞功之禮；「晝日三接」，示康侯之寵；「田獲三品」，示得功之多；「三日不食」，示於行之義。易以三為貴，審矣。易象又以「七日」言者，復之「七日來複」，聖人以為天行，而子夏、胡安定、伊川蘇氏諸解，皆以坤極六位，而反於坤之復，其數七日，凡歷七爻，以一爻為一日，故云「七日」也。而震六二：「喪貝，勿逐，七日得。」既濟六二：「婦喪其茀」，亦曰：「勿逐，七日得。」小象以七日得，為以中道也。聖人於復言天行，於既濟言中道，則七日象數，易固有則也，奚容以私意臆度論？</p><p>文王作卦下辭，多以「利涉大川」為象，或言「不利涉大川」者，或以爻辭中亦言「利涉大川」者。蓋聖人觀卦象之難，如需下三陽，上誅坎險，其事至難。如大川之難涉，必勇往有為，則事遂，故以「利涉大川」為象。故需之彖曰：「利涉大川，往有功也。」又如蠱弊難拯，如大川之難涉，必勇往有為則事遂，故曰：「利涉大川，往有事也。」如訟之群剛，希冀非望，如涉川之難，非可勇往利涉，故曰：「不利涉大川，入於淵也。」若夫同人之「利涉大川」者，以九五與六二之同，多有難阻，乾興大師克之，得與二遇，故彖言「同人於野，亨，利涉大川，乾行也」，乾用大師克相遇，故以「利涉大川」為象也。大畜利涉大川者，大畜君子當朝廷養賢之時，不家食致吉，雖勇往求君，有為亦所利也。九三爻言「利有攸往」，與上合志，即涉川應天之旨也。後益卦「利涉大川」，渙卦「利涉大川，中孚利涉大川」者，三卦皆巽體在上，六四有功，故三卦彖辭益言「木道乃行」，渙言「乘木有功」，中孚言「乘木舟虛」也。木即巽六四也。六四有功，故言木道乃行，乘木有功也。外爻辭謙初六謙謙卑以自牧，雖事之難，君子亦可勇往用涉也。頤上九：既由我頤養於天下，雖事如涉川之難，亦利涉也。若夫未濟六三：「未濟，徵兇，利涉大川。」蓋六三當未濟而上徵則兇，雖上徵之難，亦可勇而有為而利涉也。故雖「未濟徵兇」，而利涉有為也。若夫頤六五：「拂經為頤，居貞則吉」，則不可涉川為難事，故言「不可涉大川」也。聖人以涉川為象，皆以卦爻事象之難者，立文取譬，有利有不利，其旨深矣。後之學者，當自考之。</p><p>蠱卦「先甲三日，後甲三日」，言前治後治也。未蠱之前，前可為大治矣。飭蠱之後，後尤為大治也。「先甲三日」，言承前治之統也。「後甲三日」，言垂後治之統也。故彖辭謂「終則有始，天行也」。前治已終矣，後治今始也。蠱所以為元亨而天下治也。巽卦「先庚三日」，言申天命未已也。旅君失國之先，天命已久矣。巽君中興之後，天命方新也。先庚三日，天始命於國家者，其歷數可謂長矣。後庚三日，天覆命於國者，其歷數尤為長也。故彖辭謂重巽以申命於三日之先，知天命之未改也。申其命於三日之後，知天命之尤長也。巽所以申命行事也。或者立為甲庚之圖，則非矣。</p><p>周建子為正月，一陽生為復，二月醜為臨，剛浸而長。三月三陽泰，四月四陽大壯，五月五陽而夬，六月乾，七月姤，一陰生，至八月遁，二陰浸長則陽遁，君子道消，故聖人於臨言八月有兇，消不久也。後至否，三陰盛也；觀，四陰盛也；剝，五陰盛也。至亥月坤，純陰用事，陰之消陽至此極矣。然後至周建子為陽生之月，聖人於臨言八月有兇，蓋臨二陽長之時，至八月當二陰長之卦，陰長則陽消，故至遁時八月有兇，聖人戒之於早也。籲，聖人立陽長卦名有六，曰復臨泰大壯夬乾。又立陰長卦名有六，曰姤遁否觀剝坤。蓋託陰陽消長之序，為君子小人進退之候。當二陽之臨，曷可不存二陰之遁於八月哉？聖人為君子慮者切矣。</p><p>卦以震、巽之長，坎、離之中，艮、兌之少，可為夫婦。而質之易爻不然。蓋卦爻以上下二體所屬剛柔陰陽為夫婦之象。如漸九三爻言：「夫徵不復，婦孕不育。」蓋「夫徵」言九三也，「婦孕」言六二也。九三之「徵不復」而離群醜，故六二之「婦孕不育」也。又漸九五爻言：「婦三歲不孕，終莫之勝，吉。」謂九五之君不庇於六四，故六四之「婦三歲不孕」也。又如蒙卦六三爻言：「勿用取女，見金夫，不有躬，無攸利。」言六三之陰下求九二，以九二為「金夫」，不有躬而相從，故小象以為「行不順也」。「金夫」言剛夫也。前輩諸解作人之多金，六三說而從之，恐聖人取象之意，不如是之屑。如「金夫」、「金柅」，皆以剛取義也。又如大過卦諸爻言「老夫」「女妻」、「老婦」、「士夫」，有老少之別者，以大過卦剛過為象，故於爻有老少之辨也。九二爻言「老夫」者，言九二也。「女妻」者，言初六也。九二「老夫」得初六柔在下而陰生，是女妻也，故有老夫、「女妻」之象。九五、上六爻言「老婦」、「士夫」者，「士夫」言九五也，「老婦」言上六也。上六「老婦」得九五「士夫」為可醜也。茲夫婦取象，又以陰陽老少為象，學者又當詳之。</p><p>易自中興之後，國家亦多變故矣。聖人作巽後爻辭，言國家時變不一也。雖更歷千萬代，其應如響。蓋天命所繫，聖人豈隱於易哉？巽上之「喪其資斧」，言中興之君，太阿倒持，優遊不斷之象也。兌五之「孚於剝」，言中興之後，信讒佞，遠忠直，而得位於上。如漢元帝信許氏，殺蕭望之之類也。渙五之「渙王居」，蓋後世東遷之象也。渙上之「血去遠害」，蓋秦時望夷宮中，唐憲、敬遇害之象也。遂致節九五「甘節，往有尚」，得位中之吉，如唐稱國舅、國㸙，甘言免患之類也。傳至屯蒙，屯九五位於小人之中，膏澤不流，蒙之童幼，順巽倖免。至於需之興戎，而小人出穴，小人窟穴甫除，而訟之群奸已睥睨於旁，巽後大變極矣。幸而師、比之真人勃興，師之用眾，比之推戴，明陽之建極未幾。同人之應君，大有之柔位，明陰之建極，由巽而訟，歷數可推。陰陽建極，而天命延長，不可測矣。</p><p>易之卦爻言無咎者多矣。聖人謂無咎者，善補過也。如睽初九「見惡人，無咎」，見惡人，以闢咎也。離初九「履錯然，敬之，無咎」，履錯之敬，以闢咎也。茲補過而免咎者也。有何咎、何其咎者，小畜初九「復自道，何其咎，吉」、隨九四「有孚在道，以明，何咎」？睽六五「厥宗噬膚，往何咎」？茲其過，咎之必無者也。有義無咎者：復六三「頻復」之厲，義無咎也；解初六剛柔之際，義無咎也；漸初六「小子」之厲，義無咎也；既濟初九「曳其輪」，義無咎也。至大有初九則曰「無交害，匪咎，艱則無咎」。然有不可歸咎於人者，如同人初九「出門同人」，又誰咎也；解六三自我致戎，又誰咎也；節六三不節之嗟，又誰咎也？然大過上六「過涉滅頂，兇，無咎」，過涉之兇，不可咎也，茲取兇之不可怨咎者也。有自取其咎者，如夬初九「往不勝為咎」，不勝而往，咎也。有「無大咎」者，如蠱九三「小有悔，無大咎」，姤九三「厲，無大咎」。有「終無咎」者，如習坎六四「納約自牖，終無咎」，夬九三之象「君子夬夬，終無咎也」。易言「無咎」多端矣，非可一義為言也。雖均曰「無咎」，易爻變易以貢，神而明之，則存乎人焉。乾九三雖危而無咎，九四或疑而無咎，茲善補過而無咎，異乎前之無咎多等者矣。</p>',20)])])}const m=a(n,[["render",c]]);export{h as __pageData,m as default};
